#!/usr/bin/env bash
# Pass or fail check for the one-hour Gemma test. It prints one line per check
# and exits non-zero unless every check passes. Do not edit this file.
set -u
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT" || exit 99
# shellcheck disable=SC1091
source "$ROOT/scripts/env.sh"

BASE="build/s2-base"
WASM="target/near/tusdc/tusdc.wasm"
TEST_NAME="vault_rejects_every_caller_but_parent"
LOG="$(mktemp -t tusdc-check)"
fails=0

pass() { printf 'PASS %s\n' "$1"; }
fail() { printf 'FAIL %s: %s\n' "$1" "$2"; fails=$((fails + 1)); }

# 1. Rules, plan, docs and this script are unchanged.
if git diff --quiet "$BASE" -- scripts AGENTS.md PLAN.md docs rust-toolchain.toml tests Cargo.toml Cargo.lock contracts/tusdc/Cargo.toml contracts/test-token contracts/vault \
  && [ -z "$(git status --porcelain -- scripts AGENTS.md PLAN.md docs rust-toolchain.toml tests Cargo.toml Cargo.lock contracts/tusdc/Cargo.toml contracts/test-token contracts/vault)" ]; then
  pass "protected files unchanged"
else
  fail "protected files unchanged" "only contracts/vault/src/lib.rs may change. Restore the other files with git checkout."
fi

# 2. No tool-call text leaked into file names or contents.
bad="$(python3 -I - <<'PY'
import os
tokens = ('<|tool_call', '<tool_call|>', '<|channel>', '<channel|>', '<|"|>', '<|tool_response')
skip_dirs = {'.git', 'target', 'node_modules'}
skip_files = {'PLAN.md', 'scripts/tusdc-check.sh'}
found = []
for folder, subs, files in os.walk('.'):
    subs[:] = [s for s in subs if s not in skip_dirs and not os.path.join(folder, s).startswith('./docs/sources')]
    for name in files + subs:
        if any(c in name for c in '`<>{}|\n'):
            found.append('name: ' + repr(os.path.join(folder, name))[:100])
    for name in files:
        path = os.path.relpath(os.path.join(folder, name), '.')
        if path in skip_files or path.startswith('scripts/') or os.path.getsize(path) > 2_000_000:
            continue
        try:
            text = open(path, encoding='utf-8', errors='ignore').read()
        except OSError:
            continue
        if any(t in text for t in tokens):
            found.append('content: ' + path)
print('\n'.join(found[:10]))
PY
)"
if [ -z "$bad" ]; then
  pass "no corrupted file names or contents"
else
  fail "no corrupted file names or contents" "delete or rewrite these: $bad"
fi

# 3. The contract builds with the plan's command and is small enough to deploy.
rm -f "$WASM"
if cargo near build non-reproducible-wasm --locked --no-abi --manifest-path contracts/tusdc/Cargo.toml >"$LOG" 2>&1 && [ -s "$WASM" ]; then
  pass "tusdc builds to $WASM"
else
  fail "tusdc builds to $WASM" "build failed. Last lines:"
  tail -25 "$LOG"
fi

# 4. Every visible check passes.
if cargo test --locked -p tests --test tusdc_spec -- --test-threads=3 >"$LOG" 2>&1 \
  && grep -q 'test result: ok. 9 passed' "$LOG"; then
  pass "all 9 checks in tests/tests/tusdc_spec.rs passed"
else
  fail "all 9 checks in tests/tests/tusdc_spec.rs passed" "details:"
  grep -E '^test .* (ok|FAILED)$|panicked|^error' "$LOG" | head -30
  tail -12 "$LOG"
fi

rm -f "$LOG"
if [ "$fails" -eq 0 ]; then
  echo "TUSDC CHECK PASS"
  exit 0
fi
echo "TUSDC CHECK FAIL: $fails checks failed"
exit 1
